let isDragging = false;
let dragAction = null;  // "select" | "deselect"
let startRow = null;
let startCol = null;

function clearPreview() {
  board.querySelectorAll(".preview").forEach(c => c.classList.remove("preview"));
}

function applyPreview(r1, c1, r2, c2) {
  clearPreview();
  const rMin = Math.min(r1, r2), rMax = Math.max(r1, r2);
  const cMin = Math.min(c1, c2), cMax = Math.max(c1, c2);
  for (let r = rMin; r <= rMax; r++) {
    for (let c = cMin; c <= cMax; c++) {
      cells[r][c].classList.add("preview");
    }
  }
}

function commitPreview(r1, c1, r2, c2) {
  const rMin = Math.min(r1, r2), rMax = Math.max(r1, r2);
  const cMin = Math.min(c1, c2), cMax = Math.max(c1, c2);
  for (let r = rMin; r <= rMax; r++) {
    for (let c = cMin; c <= cMax; c++) {
      const cell = cells[r][c];
      cell.classList.remove("preview");
      if (dragAction === "select") {
        cell.classList.add("selected");
      } else {
        cell.classList.remove("selected");
      }
    }
  }
}

board.addEventListener("dragstart", (e) => e.preventDefault());

board.addEventListener("mousedown", (e) => {
  e.preventDefault();
  const cell = e.target.closest(".cell");
  if (!cell) return;

  isDragging = true;
  startRow = parseInt(cell.dataset.row);
  startCol = parseInt(cell.dataset.col);
  dragAction = cell.classList.contains("selected") ? "deselect" : "select";

  applyPreview(startRow, startCol, startRow, startCol);
});

board.addEventListener("mouseover", (e) => {
  if (!isDragging) return;
  const cell = e.target.closest(".cell");
  if (!cell) return;

  const curRow = parseInt(cell.dataset.row);
  const curCol = parseInt(cell.dataset.col);
  applyPreview(startRow, startCol, curRow, curCol);
});

document.addEventListener("mouseup", (e) => {
  if (!isDragging) return;

  const el = document.elementFromPoint(e.clientX, e.clientY);
  const cell = el && el.closest(".cell");

  if (cell) {
    const endRow = parseInt(cell.dataset.row);
    const endCol = parseInt(cell.dataset.col);
    commitPreview(startRow, startCol, endRow, endCol);
  } else {
    clearPreview();
  }

  isDragging = false;
  dragAction = null;
  startRow = null;
  startCol = null;
});

