// The committed selection is always one rectangle (or null if nothing selected)
let selection = null; // { rMin, cMin, rMax, cMax }

let isDragging = false;
let dragStartRow = null;
let dragStartCol = null;

// ── Helpers ────────────────────────────────────────────────────────────

function clearClass(cls) {
  board.querySelectorAll("." + cls).forEach(c => c.classList.remove(cls));
}

// Paint every cell in a rect with a given class
function paintRect(rMin, cMin, rMax, cMax, cls) {
  for (let r = rMin; r <= rMax; r++)
    for (let c = cMin; c <= cMax; c++)
      cells[r][c].classList.add(cls);
}

// Redraw the committed selection
function renderSelection() {
  clearClass("selected");
  if (selection) {
    paintRect(selection.rMin, selection.cMin, selection.rMax, selection.cMax, "selected");
  }
}

// Given the current drag endpoint, compute the preview rect:
// the bounding box of (existing selection ∪ drag rectangle)
function previewRect(curRow, curCol) {
  const dragRMin = Math.min(dragStartRow, curRow);
  const dragRMax = Math.max(dragStartRow, curRow);
  const dragCMin = Math.min(dragStartCol, curCol);
  const dragCMax = Math.max(dragStartCol, curCol);

  if (!selection) {
    return { rMin: dragRMin, cMin: dragCMin, rMax: dragRMax, cMax: dragCMax };
  }
  return {
    rMin: Math.min(selection.rMin, dragRMin),
    cMin: Math.min(selection.cMin, dragCMin),
    rMax: Math.max(selection.rMax, dragRMax),
    cMax: Math.max(selection.cMax, dragCMax),
  };
}

function applyPreview(curRow, curCol) {
  clearClass("preview");
  const r = previewRect(curRow, curCol);
  paintRect(r.rMin, r.cMin, r.rMax, r.cMax, "preview");
}

// ── Events ─────────────────────────────────────────────────────────────

board.addEventListener("dragstart", (e) => e.preventDefault());

board.addEventListener("mousedown", (e) => {
  e.preventDefault();
  const cell = e.target.closest(".cell");
  if (!cell) return;

  isDragging = true;
  dragStartRow = parseInt(cell.dataset.row);
  dragStartCol = parseInt(cell.dataset.col);

  applyPreview(dragStartRow, dragStartCol);
});

board.addEventListener("mouseover", (e) => {
  if (!isDragging) return;
  const cell = e.target.closest(".cell");
  if (!cell) return;

  applyPreview(parseInt(cell.dataset.row), parseInt(cell.dataset.col));
});

document.addEventListener("mouseup", (e) => {
  if (!isDragging) return;

  const el = document.elementFromPoint(e.clientX, e.clientY);
  const cell = el && el.closest(".cell");

  clearClass("preview");

  if (cell) {
    const endRow = parseInt(cell.dataset.row);
    const endCol = parseInt(cell.dataset.col);
    const r = previewRect(endRow, endCol);

    // Single click on a cell already inside the selection → clear all
    const isSingleClick = dragStartRow === endRow && dragStartCol === endCol;
    if (isSingleClick && selection &&
        endRow >= selection.rMin && endRow <= selection.rMax &&
        endCol >= selection.cMin && endCol <= selection.cMax) {
      selection = null;
    } else {
      selection = r;
    }

    renderSelection();
  }

  isDragging = false;
  dragStartRow = null;
  dragStartCol = null;
});

