// ── Place Table ──────────────────────────────────────────────────────────
function placeTable() {
  if (!selection) return;
  const { rMin, cMin, rMax, cMax } = selection;
  const ignoreId = editingTable ? editingTable.id : null;

  if (hasConflict(rMin,cMin,rMax,cMax,ignoreId)) {
    btnTable.classList.add("conflict");
    setTimeout(() => btnTable.classList.remove("conflict"), 600);
    return;
  }

  if (editingTable) {
    // Re-place the edited table with its new bounds
    const t = editingTable;
    editingTable = null;
    delete t._editBackup;
    t.rMin=rMin; t.cMin=cMin; t.rMax=rMax; t.cMax=cMax;
    stampTable(t);
    positionEl(t);
    t.el.style.display = "";
    selection = null;
    renderSelection();
    return;
  }

  const color = TABLE_COLORS[tableCount % TABLE_COLORS.length];
  const id    = tableCount++;
  const label = `Table ${id + 1}`;

  const el = document.createElement("div");
  el.className = "table-rect";
  el.style.backgroundColor = color + "44";
  el.style.borderColor = color;
  el.textContent = label;

  const t = { id, rMin, cMin, rMax, cMax, color, label, el };
  tables.push(t);
  positionEl(t);
  stampTable(t);
  overlay.appendChild(el);
  el.addEventListener("mousedown", (e) => onTableMouseDown(e, t));
  el.addEventListener("click",     (e) => { e.stopPropagation(); selectTable(t); });

  selection = null;
  renderSelection();
}

