function onTableMouseDown(e, t) {
  e.preventDefault();
  e.stopPropagation();
  const {row,col} = boardCoords(e);
  moveOffsetRow = row - t.rMin;
  moveOffsetCol = col - t.cMin;
  movingTable   = t;
  let hasMoved  = false;
  t.el.classList.add("moving");

  // ghost mirrors table size
  ghost = document.createElement("div");
  ghost.className = "table-ghost";
  ghost.style.width  = ((t.cMax - t.cMin + 1) * CELL) + "px";
  ghost.style.height = ((t.rMax - t.rMin + 1) * CELL) + "px";
  ghost.style.left   = t.el.style.left;
  ghost.style.top    = t.el.style.top;
  ghost.style.display = "none"; // hidden until mouse actually moves
  overlay.appendChild(ghost);

  // We need a one-time mousemove to detect whether this is a drag
  function onFirstMove() {
    hasMoved = true;
    ghost.style.display = "";
    document.removeEventListener("mousemove", onFirstMove);
  }
  document.addEventListener("mousemove", onFirstMove);

  // One-time mouseup to resolve click vs drag
  function onUp(upE) {
    document.removeEventListener("mouseup", onUp, true);
    document.removeEventListener("mousemove", onFirstMove);
    t.el.classList.remove("moving");
    overlay.removeChild(ghost);
    ghost = null;

    if (!hasMoved) {
      // It was a bare click — select this table, don't move it
      movingTable = null;
      selectTable(selectedTable === t ? null : t);
      return;
    }

    // It was a drag — commit the move (handled by the global mouseup below)
    // We do nothing here; the global handler fires on the same event
  }
  document.addEventListener("mouseup", onUp, true);
}

