  t.rMin = t._editBackup.rMin; t.cMin = t._editBackup.cMin;
  t.rMax = t._editBackup.rMax; t.cMax = t._editBackup.cMax;
  delete t._editBackup;
  stampTable(t);
  positionEl(t);
  t.el.style.display = "";
